```go
func (s *Server) DispatchLink(ctx context.Context, dest net.Destination, link *transport.Link) error {
	if dest.Address != muxCoolAddress {
		return s.dispatcher.DispatchLink(ctx, dest, link)
	}
	worker, err := NewServerWorker(ctx, s.dispatcher, link)
	if err != nil {
		return err
	}
	select {
	case <-ctx.Done():
	case <-worker.done.Wait():
	}
	return nil
}
```

这里直接 return 回 VLESS 入站，结束，~~本来如果依赖 `common.Interrupt(link.Writer)` 来结束连接就很抽象，很多都没这接口~~

> 也就是说 VMess、Freedom 这俩 outbound 实现了只调用到 TUN 的 CloseWrite() 而非 Close()？

